function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'HitCounter' || args[0].length !== 0) return 'Start with HitCounter and no arguments.';
  if (operations.length - 1 > 300) return 'At most 300 calls to hit and getHits.';
  let last = 1;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'hit' && operations[i] !== 'getHits') return 'Only hit and getHits can follow the constructor.';
    if (args[i].length !== 1 || !Number.isInteger(args[i][0])) return 'hit and getHits each take one whole-number timestamp.';
    const timestamp = args[i][0];
    if (timestamp < 1 || timestamp > 2000000000) return 'timestamp is from 1 to 2 * 10^9.';
    if (timestamp < last) return 'Timestamps must never decrease from one call to the next.';
    last = timestamp;
  }
  return null;
}

