class HitCounter {
  constructor() {
    this.queue = [];
    this.head = 0;
  }

  hit(timestamp) {
    this.queue.push(timestamp);
  }

  getHits(timestamp) {
    while (this.head < this.queue.length && this.queue[this.head] <= timestamp - 300) {
      this.head++;
    }
    return this.queue.length - this.head;
  }
}

