class HitCounter {
  constructor() {
    this.all = [];
  }
  hit(timestamp) {
    this.all.push(timestamp);
  }
  getHits(timestamp) {
    let count = 0;
    for (const t of this.all) if (t > timestamp - 300 && t <= timestamp) count++;
    return count;
  }
}

