function generate(rand, size) {
  const calls = size === 'large' ? 300 : 1 + Math.floor(rand() * 14);
  const operations = ['HitCounter'];
  const args = [[]];
  const top = 2000000000;
  let time = rand() < 0.2 ? top - Math.floor(rand() * 3000) - 1 : 1 + Math.floor(rand() * 400);
  const hitRate = 0.4 + rand() * 0.4;
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    let step;
    if (roll < 0.3) step = 0;
    else if (roll < 0.75) step = Math.floor(rand() * (size === 'large' ? 40 : 120));
    else if (roll < 0.95) step = 299 + Math.floor(rand() * 3);
    else step = 1000 + Math.floor(rand() * 100000);
    time = Math.min(top, time + step);
    operations.push(rand() < hitRate ? 'hit' : 'getHits');
    args.push([time]);
  }
  return [operations, args];
}
